def stagehand_navigate(session_id, url, **_extra):
    import json, os, datetime, re, time, hashlib, random, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0035000" if __import__("os").path.isdir("./environment_mix/0035000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix, s):
        if not isinstance(s, str):
            return False
        return re.match(rf"^{re.escape(prefix)}[0-9A-HJKMNP-TV-Z]{{16,}}$", s) is not None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        rand = "".join(random.choice(alphabet) for _ in range(20))
        ts = int(time.time() * 1000)
        ts32 = ""
        for _ in range(10):
            ts, r = divmod(ts, 32)
            ts32 = alphabet[r] + ts32
        return prefix + ts32 + rand

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _today_key():
        return datetime.datetime.utcnow().date().isoformat()

    def _log_call(api_key_id, workspace_id, status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("stg_req_"),
            "endpoint": "stagehand_navigate",
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _ensure_usage_row(usages, workspace_id, day):
        for r in usages:
            if r.get("workspace_id") == workspace_id and r.get("day") == day:
                r.setdefault("sessions_created", 0)
                r.setdefault("commands_enqueued", 0)
                r.setdefault("screenshots_created", 0)
                r.setdefault("storage_bytes", 0)
                return r
        row = {
            "workspace_id": workspace_id,
            "day": day,
            "sessions_created": 0,
            "commands_enqueued": 0,
            "screenshots_created": 0,
            "storage_bytes": 0,
            "updated_at": now
        }
        usages.append(row)
        return row

    def _enforce_quotas_for_command(workspace):
        usages = _load("usage_counters.json")
        if not isinstance(usages, list):
            usages = []
        u = _ensure_usage_row(usages, workspace["id"], _today_key())
        q = workspace.get("quota_commands_per_day", 0)
        if not isinstance(q, int) or q < 0:
            q = 0
        if u.get("commands_enqueued", 0) >= q:
            _save("usage_counters.json", usages)
            return None, _err("QUOTA_EXCEEDED", "Daily command quota exceeded.", quota="quota_commands_per_day", limit=q)
        u["commands_enqueued"] = int(u.get("commands_enqueued", 0)) + 1
        u["updated_at"] = now
        _save("usage_counters.json", usages)
        return u, None

    def _expire_artifacts_for_session_if_needed(workspace_id, session):
        # Expire artifacts if session expires_at has passed.
        exp = _parse_dt(session.get("expires_at"))
        if exp is None:
            return
        if exp > datetime.datetime.utcnow():
            return
        arts = _load("page_artifacts.json")
        if not isinstance(arts, list):
            return
        changed = False
        for a in arts:
            if a.get("workspace_id") == workspace_id and a.get("session_id") == session.get("id") and a.get("status") == "available":
                a["status"] = "expired"
                # underlying blob deleted in real system: simulate by clearing blob_url
                if a.get("artifact_type") == "screenshot":
                    a["blob_url"] = None
                a["updated_at"] = now
                changed = True
        if changed:
            _save("page_artifacts.json", arts)

    def _enforce_storage_cap(workspace_id, quota_storage_mb):
        # If storage cap exceeded, expire oldest available artifacts until within cap.
        arts = _load("page_artifacts.json")
        if not isinstance(arts, list):
            arts = []
        cap_bytes = max(0, int(quota_storage_mb)) * 1024 * 1024
        # compute current storage bytes from available artifacts with byte_size
        avail = [a for a in arts if a.get("workspace_id") == workspace_id and a.get("status") == "available"]
        def _bs(a):
            bs = a.get("byte_size")
            return int(bs) if isinstance(bs, int) and bs >= 0 else 0
        total = sum(_bs(a) for a in avail)
        if cap_bytes == 0:
            # cap=0 => expire all available artifacts
            if any(a.get("status") == "available" and a.get("workspace_id") == workspace_id for a in arts):
                for a in arts:
                    if a.get("workspace_id") == workspace_id and a.get("status") == "available":
                        a["status"] = "expired"
                        if a.get("artifact_type") == "screenshot":
                            a["blob_url"] = None
                        a["updated_at"] = now
                _save("page_artifacts.json", arts)
            return
        if total <= cap_bytes:
            return
        # expire by created_at oldest first
        def _created(a):
            dt = _parse_dt(a.get("created_at"))
            return dt or datetime.datetime.min
        avail_sorted = sorted(avail, key=_created)
        changed = False
        for a in avail_sorted:
            if total <= cap_bytes:
                break
            if a.get("status") != "available":
                continue
            a["status"] = "expired"
            if a.get("artifact_type") == "screenshot":
                a["blob_url"] = None
            a["updated_at"] = now
            total -= _bs(a)
            changed = True
        if changed:
            _save("page_artifacts.json", arts)

    # Validate inputs
    if not _ulid_like("stg_sess_", session_id):
        _log_call(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid session_id format.", field="session_id")
    if not isinstance(url, str) or not url.strip():
        _log_call(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing or invalid url.", field="url")
    u = urllib.parse.urlparse(url.strip())
    if u.scheme not in ("http", "https") or not u.netloc:
        _log_call(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "URL must be absolute (http/https).", field="url")

    # Resolve session/workspace/auth context (ambient auth or API key via session.api_key_id)
    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if s.get("id") == session_id), None)
    if not sess:
        _log_call(None, None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Session not found.", session_id=session_id)

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if w.get("id") == sess.get("workspace_id")), None)
    if not ws:
        _log_call(None, sess.get("workspace_id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible workspace context for this request.")
    if ws.get("status") != "active":
        _log_call(sess.get("api_key_id"), ws.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

    api_key_id = sess.get("api_key_id")
    if api_key_id is not None:
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        key = next((k for k in keys if k.get("id") == api_key_id and k.get("workspace_id") == ws.get("id")), None)
        if not key or key.get("status") != "active":
            _log_call(api_key_id, ws.get("id"), "error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is not authorized for this operation.")

    # Retention enforcement hooks
    _expire_artifacts_for_session_if_needed(ws["id"], sess)
    _enforce_storage_cap(ws["id"], ws.get("quota_storage_mb", 0))

    # Session lifecycle check
    if sess.get("status") in ("ended", "error"):
        _log_call(api_key_id, ws.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot enqueue commands on an ended/error session.", session_status=sess.get("status"))

    # Quota: command enqueue
    _, qerr = _enforce_quotas_for_command(ws)
    if qerr:
        _log_call(api_key_id, ws.get("id"), "error", qerr["error"]["code"])
        return qerr

    # Allocate sequence_no atomically-ish (single file)
    commands = _load("session_commands.json")
    if not isinstance(commands, list):
        commands = []
    max_seq = 0
    for c in commands:
        if c.get("session_id") == session_id:
            sn = c.get("sequence_no")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn
    seq = max_seq + 1

    cmd_id = _new_id("stg_cmd_")
    cmd = {
        "id": cmd_id,
        "session_id": session_id,
        "workspace_id": ws["id"],
        "api_key_id": api_key_id,
        "tool_name": "stagehand_navigate",
        "status": "queued",
        "sequence_no": seq,
        "input": {"url": url.strip()},
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    # uniqueness constraint unique(session_id, sequence_no)
    if any(c.get("session_id") == session_id and c.get("sequence_no") == seq for c in commands):
        _log_call(api_key_id, ws.get("id"), "error", "CONFLICT")
        return _err("CONFLICT", "Command sequence conflict. Please retry.", session_id=session_id)

    commands.append(cmd)
    _save("session_commands.json", commands)

    # Execute state transitions: queued -> running -> succeeded
    # queued -> running
    cmd["status"] = "running"
    cmd["started_at"] = now
    cmd["updated_at"] = now
    _save("session_commands.json", commands)

    # Update session to running if it was created
    if sess.get("status") == "created":
        sess["status"] = "running"
        sess["updated_at"] = now

    # Simulate navigation side-effects on session fields
    sess["current_url"] = url.strip()[:4096]
    sess["current_title"] = f"Title of {sess['current_url']}"[:512]
    sess["last_dom_hash"] = hashlib.sha256((sess["current_url"] + "|" + (sess.get("current_title") or "")).encode("utf-8")).hexdigest()
    sess["last_activity_at"] = now
    sess["updated_at"] = now
    _save("browser_sessions.json", sessions)

    # running -> succeeded
    cmd["status"] = "succeeded"
    cmd["finished_at"] = now
    cmd["updated_at"] = now
    _save("session_commands.json", commands)

    # Update api key last_used_at if present
    if api_key_id is not None:
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            changed = False
            for k in keys:
                if k.get("id") == api_key_id:
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    changed = True
                    break
            if changed:
                _save("api_keys.json", keys)

    _log_call(api_key_id, ws.get("id"), "ok", None)
    return {
        "command": cmd,
        "session": {
            "id": sess.get("id"),
            "status": sess.get("status"),
            "current_url": sess.get("current_url"),
            "current_title": sess.get("current_title"),
            "last_activity_at": sess.get("last_activity_at"),
            "updated_at": sess.get("updated_at")
        }
    }

