                _save("api_keys.json", keys)

    _log_call(api_key_id, ws.get("id"), "ok", None)
    return {
        "command": cmd,
        "artifact": art
    }

def screenshot(session_id, **_extra):
    import json, os, datetime, re, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0035000" if __import__("os").path.isdir("./environment_mix/0035000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None: return None
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _ulid(prefix):
        # 26 chars Crockford-ish
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(now.timestamp() * 1000)
        # 10 chars time component base32
        time_part = ""
        x = ms
        for _ in range(10):
            time_part = alphabet[x % 32] + time_part
            x //= 32
        rnd = os.urandom(10)
        # 16 chars randomness base32 (80 bits)
        r = int.from_bytes(rnd, "big")
        rand_part = ""
        for _ in range(16):
            rand_part = alphabet[r % 32] + rand_part
            r //= 32
        return f"{prefix}{time_part}{rand_part}"

    def _log(status, workspace_id=None, api_key_id=None, endpoint="screenshot", error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _ulid("stg_req_"),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now)
        })
        _save("request_logs.json", logs)

    def _resolve_context_for_session(sess_row):
        # Ambient auth: pick a usable API key for the session's workspace if any; else proceed without.
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list): api_keys = []
        ws_id = sess_row.get("workspace_id")
        # Prefer the session's api_key_id if active
        sid_key = sess_row.get("api_key_id")
        if sid_key:
            for k in api_keys:
                if k.get("id") == sid_key and k.get("workspace_id") == ws_id and k.get("status") == "active":
                    return ws_id, k.get("id")
        # Else any active key in workspace
        for k in api_keys:
            if k.get("workspace_id") == ws_id and k.get("status") == "active":
                return ws_id, k.get("id")
        # Else no key (allowed for ambient)
        return ws_id, None

    def _count_today(commands, workspace_id, tool_name=None):
        start = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        c = 0
        for r in commands:
            if r.get("workspace_id") != workspace_id:
                continue
            if tool_name is not None and r.get("tool_name") != tool_name:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if start <= dt < end:
                c += 1
        return c

    def _enforce_retention(workspace, sessions, artifacts):
        # Expire artifacts for expired sessions; also enforce storage cap.
        changed = False
        ws_id = workspace.get("id")

        # Session expiry
        for sess in sessions:
            if sess.get("workspace_id") != ws_id:
                continue
            exp = _parse_dt(sess.get("expires_at"))
            if exp is not None and exp <= now:
                # Session may remain running/created but artifacts must expire; real systems might end session too,
                # but business rule explicitly says retention enforced by expires_at.
                for art in artifacts:
                    if art.get("workspace_id") == ws_id and art.get("session_id") == sess.get("id") and art.get("status") == "available":
                        art["status"] = "expired"
                        art["updated_at"] = _iso(now)
                        # delete underlying blob url for screenshots
                        if art.get("artifact_type") == "screenshot":
                            art["blob_url"] = None
                        changed = True

        # Storage cap (soft cap): expire oldest available artifacts until under cap.
        cap_mb = workspace.get("quota_storage_mb")
        try:
            cap_bytes = int(cap_mb) * 1024 * 1024
        except Exception:
            cap_bytes = 0
        if cap_bytes >= 0:
            avail = [a for a in artifacts if a.get("workspace_id") == ws_id and a.get("status") == "available"]
            def size_of(a):
                bs = a.get("byte_size")
                try:
                    return int(bs) if bs is not None else 0
                except Exception:
                    return 0
            total = sum(size_of(a) for a in avail)
            if total > cap_bytes and cap_bytes >= 0:
                # expire oldest first
                def created(a):
                    dt = _parse_dt(a.get("created_at"))
                    return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                avail_sorted = sorted(avail, key=created)
                for a in avail_sorted:
                    if total <= cap_bytes:
                        break
                    total -= size_of(a)
                    a["status"] = "expired"
                    a["updated_at"] = _iso(now)
                    if a.get("artifact_type") == "screenshot":
                        a["blob_url"] = None
                    changed = True
        return changed

    # Validate input
    if not isinstance(session_id, str):
        _log("error", None, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "session_id must be a string")
    if not re.match(r"^stg_sess_[0-9A-HJKMNP-TV-Z]{16,}$", session_id):
        _log("error", None, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "session_id is invalid")

    # Load store
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    commands = _load("session_commands.json")
    artifacts = _load("page_artifacts.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(commands, list): commands = []
    if not isinstance(artifacts, list): artifacts = []

    sess = next((s for s in sessions if s.get("id") == session_id), None)
    if not sess:
        _log("error", None, None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Session not found")

    ws = next((w for w in workspaces if w.get("id") == sess.get("workspace_id")), None)
    if not ws:
        _log("error", sess.get("workspace_id"), None, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for session")

    if ws.get("status") != "active":
        _log("error", ws.get("id"), None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active")

    workspace_id, api_key_id = _resolve_context_for_session(sess)
    # If there are API keys but the session's recorded api_key_id is revoked, refuse new commands
    if api_key_id:
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if not key_row or key_row.get("status") != "active":
            _log("error", workspace_id, api_key_id, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is not authorized")
        # Update last_used_at
        key_row["last_used_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)

    # Reject new commands if session ended/error
    if sess.get("status") in ("ended", "error"):
        _log("error", workspace_id, api_key_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Session is not accepting new commands")

    # Enforce quotas
    try:
        quota_cmd = int(ws.get("quota_commands_per_day"))
    except Exception:
        quota_cmd = 0
    used_cmd = _count_today(commands, workspace_id, tool_name=None)
    if quota_cmd >= 0 and used_cmd >= quota_cmd:
        _log("error", workspace_id, api_key_id, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily command quota exceeded", quota="quota_commands_per_day", limit=quota_cmd, used=used_cmd)

    try:
        quota_ss = int(ws.get("quota_screenshots_per_day"))
    except Exception:
        quota_ss = 0
    used_ss = _count_today(commands, workspace_id, tool_name="screenshot")
    if quota_ss >= 0 and used_ss >= quota_ss:
        _log("error", workspace_id, api_key_id, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily screenshot quota exceeded", quota="quota_screenshots_per_day", limit=quota_ss, used=used_ss)

    # Allocate next sequence_no atomically (within this single-process store)
    max_seq = 0
    for c in commands:
        if c.get("session_id") == session_id:
            try:
                max_seq = max(max_seq, int(c.get("sequence_no") or 0))
            except Exception:
                pass
    seq = max_seq + 1
    if seq < 1:
        seq = 1

    # Enqueue command
    cmd_id = _ulid("stg_cmd_")
    cmd_row = {
        "id": cmd_id,
        "session_id": session_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "tool_name": "screenshot",
        "status": "queued",
        "sequence_no": seq,
        "input": {},
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    # Unique(session_id, sequence_no)
    if any((c.get("session_id") == session_id and c.get("sequence_no") == seq) for c in commands):
        _log("error", workspace_id, api_key_id, error_code="CONFLICT")
        return _err("CONFLICT", "Command sequence conflict")

    commands.append(cmd_row)

    # Execute state machine: queued -> running -> succeeded
    cmd_row["status"] = "running"
    cmd_row["started_at"] = _iso(now)
    cmd_row["updated_at"] = _iso(now)

    # Create screenshot artifact on success
    art_id = _ulid("stg_art_")
    # Deterministic-ish internal URL
    blob_url = f"blob://stagehand/{workspace_id}/{session_id}/{cmd_id}.png"
    mime_type = "image/png"
    # Fake size/checksum but consistent with stored data; content itself not stored
    sha = hashlib.sha256(f"{workspace_id}:{session_id}:{cmd_id}:{_iso(now)}".encode("utf-8")).hexdigest()
    byte_size = 256000  # ~250KB placeholder

    # Enforce unique(command_id, artifact_type)
    if any(a.get("command_id") == cmd_id and a.get("artifact_type") == "screenshot" for a in artifacts):
        _log("error", workspace_id, api_key_id, error_code="CONFLICT")
        return _err("CONFLICT", "Artifact already exists for command")

    art_row = {
        "id": art_id,
        "session_id": session_id,
        "command_id": cmd_id,
        "workspace_id": workspace_id,
        "artifact_type": "screenshot",
        "status": "available",
        "content_text": None,
        "elements": None,
        "blob_url": blob_url,
        "mime_type": mime_type,
        "byte_size": byte_size,
        "sha256": sha,
        "page_url": sess.get("current_url"),
        "page_title": sess.get("current_title"),
        "metadata": {"provider": sess.get("browser_provider"), "captured_at": _iso(now)},
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    artifacts.append(art_row)

    # Finish command
    cmd_row["status"] = "succeeded"
    cmd_row["finished_at"] = _iso(now)
    cmd_row["updated_at"] = _iso(now)

    # Update session last_activity_at
    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)

    # Retention enforcement (may expire artifacts if over storage cap / session expiry)
    retention_changed = _enforce_retention(ws, sessions, artifacts)

    # Persist
    _save("api_keys.json", api_keys)
    _save("session_commands.json", commands)
    _save("page_artifacts.json", artifacts)
    _save("browser_sessions.json", sessions)
    if retention_changed:
        # already saved artifacts/sessions above
        pass

    _log("ok", workspace_id, api_key_id)

    return {
        "command": cmd_row,
        "artifact": next((a for a in artifacts if a.get("id") == art_id), None)
    }

def stagehand_create_session(browser_provider=None, expires_in_seconds=None, metadata=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0035000" if __import__("os").path.isdir("./environment_mix/0035000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None: return None
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(now.timestamp() * 1000)
        time_part = ""
        x = ms
        for _ in range(10):
            time_part = alphabet[x % 32] + time_part
            x //= 32
        rnd = os.urandom(10)
        r = int.from_bytes(rnd, "big")
        rand_part = ""
        for _ in range(16):
            rand_part = alphabet[r % 32] + rand_part
            r //= 32
        return f"{prefix}{time_part}{rand_part}"

    def _log(status, workspace_id=None, api_key_id=None, endpoint="stagehand_create_session", error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _ulid("stg_req_"),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now)
        })
        _save("request_logs.json", logs)

    def _count_today(sessions, workspace_id):
        start = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        c = 0
        for r in sessions:
            if r.get("workspace_id") != workspace_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if start <= dt < end:
                c += 1
        return c

    # Validate inputs
    if browser_provider is not None:
        if not isinstance(browser_provider, str):
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "browser_provider must be a string")
        if browser_provider not in ("stagehand", "playwright", "chromium"):
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "browser_provider must be one of: stagehand, playwright, chromium")

    if expires_in_seconds is not None:
        if not isinstance(expires_in_seconds, int):
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "expires_in_seconds must be an integer")
        if expires_in_seconds < 60 or expires_in_seconds > 604800:
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "expires_in_seconds must be between 60 and 604800")

    if metadata is not None and not isinstance(metadata, dict):
        _log("error", None, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "metadata must be an object")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(sessions, list): sessions = []

    # Ambient auth: find a workspace that can serve the call.
    # Prefer any active workspace with at least one active API key (so we can attribute), else any active workspace.
    ws = None
    key = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        for k in api_keys:
            if k.get("workspace_id") == w.get("id") and k.get("status") == "active":
                ws = w
                key = k
                break
        if ws:
            break
    if ws is None:
        for w in workspaces:
            if w.get("status") == "active":
                ws = w
                key = None
                break
    if ws is None:
        _log("error", None, None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized workspace available")

    if key is not None and key.get("status") != "active":
        _log("error", ws.get("id"), key.get("id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked")

    workspace_id = ws.get("id")
    api_key_id = key.get("id") if key else None

    # Quota: sessions per day
    try:
        quota = int(ws.get("quota_sessions_per_day"))
    except Exception:
        quota = 0
    used = _count_today(sessions, workspace_id)
    if quota >= 0 and used >= quota:
        _log("error", workspace_id, api_key_id, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily session quota exceeded", quota="quota_sessions_per_day", limit=quota, used=used)

    # Create session
    sess_id = _ulid("stg_sess_")
    provider = "browserbase"  # schema enum requires browserbase
    ttl = expires_in_seconds if expires_in_seconds is not None else 3600
    expires_at = now + datetime.timedelta(seconds=int(ttl))

    sess_row = {
        "id": sess_id,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "status": "created",
        "browser_provider": provider,
        "provider_session_id": None,
        "current_url": None,
        "current_title": None,
        "last_dom_hash": None,
        "last_activity_at": None,
        "expires_at": _iso(expires_at),
        "created_at": _iso(now),
        "updated_at": _iso(now)
    }
    sessions.append(sess_row)

    # Update api key last_used
    if key:
        key["last_used_at"] = _iso(now)
        key["updated_at"] = _iso(now)

    _save("browser_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _log("ok", workspace_id, api_key_id)

    # Return session record (no extra wrapper specified by tool)
    return {"session": sess_row}

