def stagehand_list_sessions(status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0035000" if __import__("os").path.isdir("./environment_mix/0035000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None: return None
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(now.timestamp() * 1000)
        time_part = ""
        x = ms
        for _ in range(10):
            time_part = alphabet[x % 32] + time_part
            x //= 32
        rnd = os.urandom(10)
        r = int.from_bytes(rnd, "big")
        rand_part = ""
        for _ in range(16):
            rand_part = alphabet[r % 32] + rand_part
            r //= 32
        return f"{prefix}{time_part}{rand_part}"

    def _log(status_s, workspace_id=None, api_key_id=None, endpoint="stagehand_list_sessions", error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _ulid("stg_req_"),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now)
        })
        _save("request_logs.json", logs)

    # Validate filters
    if status is not None:
        if not isinstance(status, str):
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("created", "running", "ended", "error"):
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: created, running, ended, error")

    ca = None
    cb = None
    if created_after is not None:
        if not isinstance(created_after, str):
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_after must be an RFC3339 datetime string")
        ca = _parse_dt(created_after)
        if ca is None:
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_after must be an RFC3339 datetime string")
    if created_before is not None:
        if not isinstance(created_before, str):
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_before must be an RFC3339 datetime string")
        cb = _parse_dt(created_before)
        if cb is None:
            _log("error", None, None, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "created_before must be an RFC3339 datetime string")
    if ca and cb and cb < ca:
        _log("error", None, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_before must be >= created_after")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("error", None, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log("error", None, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", None, None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    sessions = _load("browser_sessions.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(sessions, list): sessions = []

    # Ambient auth: pick an active workspace; if multiple, pick one with an active key (for attribution).
    ws = None
    key = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        for k in api_keys:
            if k.get("workspace_id") == w.get("id") and k.get("status") == "active":
                ws = w
                key = k
                break
        if ws:
            break
    if ws is None:
        for w in workspaces:
            if w.get("status") == "active":
                ws = w
                key = None
                break
    if ws is None:
        _log("error", None, None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized workspace available")

    workspace_id = ws.get("id")
    api_key_id = key.get("id") if key else None

    # Apply workspace filter
    rows = [s for s in sessions if s.get("workspace_id") == workspace_id]

    # Apply other filters
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]
    if ca is not None:
        rows = [s for s in rows if (_parse_dt(s.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) > ca]
    if cb is not None:
        rows = [s for s in rows if (_parse_dt(s.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) < cb]

    # Sort created_at desc
    def _created(s):
        return _parse_dt(s.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    rows.sort(key=_created, reverse=True)

    # Cursor pagination: cursor is "created_at|id" of last item from previous page
    start_idx = 0
    if cursor:
        try:
            parts = cursor.split("|", 1)
            cdt = _parse_dt(parts[0])
            cid = parts[1] if len(parts) > 1 else None
            if cdt is None or not cid:
                raise ValueError("bad cursor")
            # Find first row strictly after the cursor in the sorted list (i.e., older than cursor in desc sort)
            for i, r in enumerate(rows):
                rdt = _created(r)
                rid = r.get("id")
                if rdt < cdt:
                    start_idx = i
                    break
                if rdt == cdt and rid and rid < cid:
                    # tie-break by id desc behavior: since list is desc by created_at only, use id as secondary desc
                    start_idx = i
                    break
            else:
                start_idx = len(rows)
        except Exception:
            _log("error", workspace_id, api_key_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = f"{last.get('created_at')}|{last.get('id')}"

    _log("ok", workspace_id, api_key_id)
    return {
        "sessions": page,
        "total": len(rows),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def stagehand_end_session(session_id, reason=None, **_extra):
    import json, os, datetime, time, base64, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0035000" if __import__("os").path.isdir("./environment_mix/0035000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Minimal request log (only if file exists/used in this environment)
    def _log(status, credential_id=None, workspace_id=None, meta=None):
        # Look for common log files; do not create new schema unexpectedly
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rows.append({
                    "id": "req_" + secrets.token_hex(12),
                    "service": "stagehand",
                    "endpoint": "stagehand_end_session",
                    "timestamp": now,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "workspace_id": workspace_id,
                    "credential_id": credential_id,
                    "meta": meta or {}
                })
                _save(fname, rows)
                break

    # Validate input
    if not isinstance(session_id, str):
        _log("error", meta={"error": "validation", "field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id must be a string")
    if not re.match(r"^stg_sess_[0-9A-HJKMNP-TV-Z]{16,}$", session_id):
        _log("error", meta={"error": "validation", "field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id is invalid")
    if reason is not None and not isinstance(reason, str):
        _log("error", meta={"error": "validation", "field": "reason"})
        return _err("VALIDATION_ERROR", "reason must be a string")

    sessions = _load("browser_sessions.json")
    commands = _load("session_commands.json")
    artifacts = _load("page_artifacts.json")
    workspaces = _load("workspaces.json")

    sess = next((s for s in sessions if s.get("id") == session_id), None)
    if not sess:
        _log("not_found", meta={"session_id": session_id})
        return _err("NOT_FOUND", "Session not found")

    ws = next((w for w in workspaces if w.get("id") == sess.get("workspace_id")), None)
    if not ws:
        _log("unauthorized", meta={"session_id": session_id})
        return _err("UNAUTHORIZED", "No authorized workspace context available for this session")

    # If workspace is closed, session should still be endable, but must respect lifecycle
    cur = sess.get("status")
    if cur in ("ended", "error"):
        _log("conflict", workspace_id=ws.get("id"), meta={"session_id": session_id, "status": cur})
        return _err("CONFLICT", f"Session is already {cur}")

    # Lifecycle transitions for browser_sessions: created->ended, running->ended
    allowed = {"created": ["running", "ended", "error"], "running": ["ended", "error"], "ended": [], "error": []}
    if "ended" not in allowed.get(cur, []):
        _log("conflict", workspace_id=ws.get("id"), meta={"session_id": session_id, "from": cur, "to": "ended"})
        return _err("CONFLICT", "Session cannot be transitioned to ended from its current status")

    # Transition
    sess["status"] = "ended"
    sess["updated_at"] = now
    sess["last_activity_at"] = now

    # Record reason as a best-effort audit breadcrumb without changing schema:
    # attach into a common free-form field if present/appropriate
    # (No schema field for reason; keep it harmless by storing in current_title if empty? don't do that.)
    # Instead, store as a no-op command input note by appending meta to a log file (if present).
    _log("ok", workspace_id=ws.get("id"), meta={"session_id": session_id, "reason": reason} if reason else {"session_id": session_id})

    _save("browser_sessions.json", sessions)

    # Retention enforcement: if session expires_at <= now, expire available artifacts for this session
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    expires_at = _parse_dt(sess.get("expires_at"))
    now_dt = _parse_dt(now)
    if expires_at is not None and now_dt is not None and expires_at <= now_dt:
        changed = False
        # page_artifacts lifecycle: available -> expired
        for a in artifacts:
            if a.get("session_id") == session_id and a.get("status") == "available":
                a["status"] = "expired"
                a["updated_at"] = now
                # Underlying blob deletion: represent by clearing blob_url (best-effort) for screenshots
                if a.get("artifact_type") == "screenshot":
                    a["blob_url"] = None
                changed = True
        if changed:
            _save("page_artifacts.json", artifacts)

    return {"session": sess}

def stagehand_list_artifacts(session_id, artifact_type=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0035000" if __import__("os").path.isdir("./environment_mix/0035000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, credential_id=None, workspace_id=None, meta=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rows.append({
                    "id": "req_" + secrets.token_hex(12),
                    "service": "stagehand",
                    "endpoint": "stagehand_list_artifacts",
                    "timestamp": now,
                    "status": status_str,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "workspace_id": workspace_id,
                    "credential_id": credential_id,
                    "meta": meta or {}
                })
                _save(fname, rows)
                break

    # Validate
    if not isinstance(session_id, str):
        _log("error", meta={"error": "validation", "field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id must be a string")
    if not re.match(r"^stg_sess_[0-9A-HJKMNP-TV-Z]{16,}$", session_id):
        _log("error", meta={"error": "validation", "field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id is invalid")

    if artifact_type is not None:
        if not isinstance(artifact_type, str):
            _log("error", meta={"error": "validation", "field": "artifact_type"})
            return _err("VALIDATION_ERROR", "artifact_type must be a string")
        if artifact_type not in ("extracted_text", "observed_elements", "screenshot"):
            _log("error", meta={"error": "validation", "field": "artifact_type"})
            return _err("VALIDATION_ERROR", "artifact_type is invalid")

    if status is not None:
        if not isinstance(status, str):
            _log("error", meta={"error": "validation", "field": "status"})
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("available", "deleted", "expired"):
            _log("error", meta={"error": "validation", "field": "status"})
            return _err("VALIDATION_ERROR", "status is invalid")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("error", meta={"error": "validation", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log("error", meta={"error": "validation", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", meta={"error": "validation", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    sessions = _load("browser_sessions.json")
    artifacts = _load("page_artifacts.json")
    workspaces = _load("workspaces.json")

    sess = next((s for s in sessions if s.get("id") == session_id), None)
    if not sess:
        _log("not_found", meta={"session_id": session_id})
        return _err("NOT_FOUND", "Session not found")

    ws = next((w for w in workspaces if w.get("id") == sess.get("workspace_id")), None)
    if not ws:
        _log("unauthorized", meta={"session_id": session_id})
        return _err("UNAUTHORIZED", "No authorized workspace context available for this session")

    # Retention enforcement for expired session: expire available artifacts
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    expires_at = _parse_dt(sess.get("expires_at"))
    now_dt = _parse_dt(now)
    if expires_at is not None and now_dt is not None and expires_at <= now_dt:
        changed = False
        for a in artifacts:
            if a.get("session_id") == session_id and a.get("status") == "available":
                a["status"] = "expired"
                a["updated_at"] = now
                if a.get("artifact_type") == "screenshot":
                    a["blob_url"] = None
                changed = True
        if changed:
            _save("page_artifacts.json", artifacts)

    # Filter by session + optional filters
    rows = [a for a in artifacts if a.get("session_id") == session_id]
    if artifact_type is not None:
        rows = [a for a in rows if a.get("artifact_type") == artifact_type]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]

    # Stable sort: newest first by created_at, then id
    def _key(a):
        ca = a.get("created_at") or ""
        return (ca, a.get("id") or "")
    rows.sort(key=_key, reverse=True)

    # Cursor pagination (opaque): base64url of "created_at|id"
    start_index = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            raw_s = raw.decode("utf-8")
            parts = raw_s.split("|", 1)
            if len(parts) == 2:
                c_created_at, c_id = parts
                # find first row strictly after the cursor in the sorted order
                for i, a in enumerate(rows):
                    if (a.get("created_at") or "", a.get("id") or "") < (c_created_at, c_id):
                        # since rows are sorted desc, we need to skip until we pass the cursor item
                        # Better: find exact match then start after it; otherwise start at 0
                        continue
                # exact match start after it
                for i, a in enumerate(rows):
                    if (a.get("created_at") or "") == c_created_at and (a.get("id") or "") == c_id:
                        start_index = i + 1
                        break
        except Exception:
            _log("error", workspace_id=ws.get("id"), meta={"error": "validation", "field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = rows[start_index:start_index + limit]
    has_more = (start_index + limit) < len(rows)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        token = f"{last.get('created_at') or ''}|{last.get('id') or ''}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # Return inline content for text/element artifacts, blob_url for screenshots as stored
    _log("ok", workspace_id=ws.get("id"), meta={"session_id": session_id, "returned": len(page)})

    return {
        "artifacts": page,
        "session_id": session_id,
        "total": len(rows),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }
